import{c as i,Z as e,Q as n,j as s,m as l,o as t}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"登鹳雀楼","description":"","frontmatter":{"title":"登鹳雀楼","author":"王之涣","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/3.md","filePath":"books/shici/tangshi/3.md"}'),h={name:"books/shici/tangshi/3.md"};function c(d,a,_,m,u,p){const o=e("PoemAuthor"),r=e("PoemNav");return n(),s("div",null,[a[0]||(a[0]=l('<h1 id="登鹳雀楼" tabindex="-1">登鹳雀楼 <a class="header-anchor" href="#登鹳雀楼" aria-label="Permalink to &quot;登鹳雀楼&quot;">​</a></h1><p><strong>[唐] <a href="/authors/wangzhihuan.html">王之涣</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>白日依山尽，黄河入海流。 欲穷千里目，更上一层楼。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>白日：太阳</li><li>依：依傍，靠着</li><li>尽：消失</li><li>穷：尽，使达到极点</li><li>千里目：眼界宽阔</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>夕阳依傍着西山慢慢地沉没，滔滔黄河朝着东海汹涌奔流。若想把千里的风光景物看够，那就要登上更高的一层城楼。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗写诗人在登高望远中表现出来的不凡的胸襟抱负，反映了盛唐时期人们积极向上的进取精神。前两句写所见，用极简练的笔墨描绘了祖国河山的壮丽景色；后两句写所想，道出了要站得高才看得远的哲理。全诗气势磅礴，意境深远，千百年来一直激励着中华民族昂扬向上。</p>',10)),t(o,{name:"王之涣",years:"688年－742年",desc:"字季凌，唐代著名诗人，以描写边疆风光著称。其诗气势雄浑，意境开阔，可惜作品多已散佚，传世仅六首。",link:"/authors/wangzhihuan"}),t(r)])}const P=i(h,[["render",c]]);export{b as __pageData,P as default};
